        self,
        text: str,
        tag_hint: Optional[str] = None,
    ) -> list[Element]:
        """
        returns element which match the given text.
        please note: this may (or will) also return any other element (like inline scripts),
        which happen to contain that text.

        :param text:
        :param tag_hint: when provided, narrows down search to only elements which match given tag eg: a, div, script, span
        :return:
        :rtype:
        """
        text = text.strip()
        doc = await self.send(cdp.dom.get_document(-1, True))
        search_id, nresult = await self.send(cdp.dom.perform_search(text, True))
        try:
            if nresult:
                node_ids = await self.send(
                    cdp.dom.get_search_results(search_id, 0, nresult)
                )
            else:
                node_ids = []
            await self.send(cdp.dom.discard_search_results(search_id))
        except ProtocolException:
            # the search session is dropped when the document is replaced mid-search
            return []

        if not node_ids:
            node_ids = []
        items = []
        for nid in node_ids:
            node = util.filter_recurse(doc, lambda n: n.node_id == nid)
            if not node:
                try:
                    node = await self.send(cdp.dom.describe_node(node_id=nid))
                except ProtocolException:
                    continue
                if not node:
                    continue
